CREATE EXTENSION IF NOT EXISTS pgcrypto;

DO $$ BEGIN CREATE TYPE public.app_role AS ENUM ('super_admin','admin','physiotherapist','assistant'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.workspace_type AS ENUM ('individual','clinic','sandbox'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.workspace_status AS ENUM ('active','trial','blocked','cancelled','overdue','pending_payment'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.plan_kind AS ENUM ('free','pro_monthly','pro_yearly'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.member_status AS ENUM ('active','invited','disabled'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.patient_status AS ENUM ('active','inactive'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.appointment_status AS ENUM ('scheduled','completed','cancelled','missed'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.appointment_type AS ENUM ('avaliacao','sessao','retorno','outro'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.charge_status AS ENUM ('pending','paid','overdue','cancelled'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.task_priority AS ENUM ('low','medium','high'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.task_status AS ENUM ('pending','completed','cancelled'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.note_category AS ENUM ('avaliacao','evolucao','observacao','retorno','outro'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.note_visibility AS ENUM ('private','workspace'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.theme_pref AS ENUM ('automatic','light','dark'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.use_mode AS ENUM ('professional','clinic'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;

CREATE SCHEMA IF NOT EXISTS private;
REVOKE ALL ON SCHEMA private FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public.set_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN NEW.updated_at = now(); RETURN NEW; END; $$;

CREATE TABLE public.workspaces (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, type public.workspace_type NOT NULL DEFAULT 'individual', owner_id uuid NOT NULL, plan public.plan_kind NOT NULL DEFAULT 'free', status public.workspace_status NOT NULL DEFAULT 'active', responsible_name text, responsible_email text, phone text, cnpj text, monthly_price numeric(10,2), due_date date, max_users int, internal_notes text, last_access_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.workspaces TO authenticated; GRANT ALL ON public.workspaces TO service_role; ALTER TABLE public.workspaces ENABLE ROW LEVEL SECURITY;

CREATE TABLE public.profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), auth_user_id uuid NOT NULL UNIQUE, full_name text NOT NULL DEFAULT 'Usuário', email text, phone text, avatar_url text, professional_register text, default_workspace_id uuid REFERENCES public.workspaces(id) ON DELETE SET NULL, status text NOT NULL DEFAULT 'active', last_login_at timestamptz, phone_e164 text, phone_verified_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role; ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;

CREATE TABLE public.workspace_members (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE, user_id uuid NOT NULL, role public.app_role NOT NULL DEFAULT 'physiotherapist', status public.member_status NOT NULL DEFAULT 'active', permissions jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (workspace_id, user_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.workspace_members TO authenticated; GRANT ALL ON public.workspace_members TO service_role; ALTER TABLE public.workspace_members ENABLE ROW LEVEL SECURITY;

CREATE OR REPLACE FUNCTION private.is_workspace_member(_user_id uuid, _workspace_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.workspace_members WHERE user_id = _user_id AND workspace_id = _workspace_id AND status = 'active'); $$;
CREATE OR REPLACE FUNCTION private.is_workspace_admin(_user_id uuid, _workspace_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.workspace_members WHERE user_id = _user_id AND workspace_id = _workspace_id AND status = 'active' AND role IN ('super_admin','admin')); $$;

CREATE TABLE public.platform_admins (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.platform_admins TO authenticated; GRANT ALL ON public.platform_admins TO service_role; ALTER TABLE public.platform_admins ENABLE ROW LEVEL SECURITY;

CREATE OR REPLACE FUNCTION public.is_super_admin(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.platform_admins WHERE user_id = _user_id); $$;
GRANT EXECUTE ON FUNCTION public.is_super_admin(uuid) TO authenticated;

CREATE POLICY workspaces_owner_insert ON public.workspaces FOR INSERT TO authenticated WITH CHECK (owner_id = auth.uid());
CREATE POLICY workspaces_member_select ON public.workspaces FOR SELECT TO authenticated USING (owner_id = auth.uid() OR private.is_workspace_member(auth.uid(), id) OR public.is_super_admin(auth.uid()));
CREATE POLICY workspaces_admin_update ON public.workspaces FOR UPDATE TO authenticated USING (owner_id = auth.uid() OR private.is_workspace_admin(auth.uid(), id) OR public.is_super_admin(auth.uid())) WITH CHECK (owner_id = auth.uid() OR private.is_workspace_admin(auth.uid(), id) OR public.is_super_admin(auth.uid()));
CREATE POLICY profiles_self_all ON public.profiles FOR ALL TO authenticated USING (auth_user_id = auth.uid() OR public.is_super_admin(auth.uid())) WITH CHECK (auth_user_id = auth.uid() OR public.is_super_admin(auth.uid()));
CREATE POLICY workspace_members_self_select ON public.workspace_members FOR SELECT TO authenticated USING (user_id = auth.uid() OR private.is_workspace_admin(auth.uid(), workspace_id) OR public.is_super_admin(auth.uid()));
CREATE POLICY workspace_members_self_insert ON public.workspace_members FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid() OR private.is_workspace_admin(auth.uid(), workspace_id) OR public.is_super_admin(auth.uid()));
CREATE POLICY workspace_members_admin_update ON public.workspace_members FOR UPDATE TO authenticated USING (private.is_workspace_admin(auth.uid(), workspace_id) OR public.is_super_admin(auth.uid())) WITH CHECK (private.is_workspace_admin(auth.uid(), workspace_id) OR public.is_super_admin(auth.uid()));
CREATE POLICY workspace_members_admin_delete ON public.workspace_members FOR DELETE TO authenticated USING (private.is_workspace_admin(auth.uid(), workspace_id) OR public.is_super_admin(auth.uid()));
CREATE POLICY platform_admins_self_select ON public.platform_admins FOR SELECT TO authenticated USING (user_id = auth.uid() OR public.is_super_admin(auth.uid()));
CREATE POLICY platform_admins_super_all ON public.platform_admins FOR ALL TO authenticated USING (public.is_super_admin(auth.uid())) WITH CHECK (public.is_super_admin(auth.uid()));

CREATE TABLE public.patients (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE, full_name text NOT NULL, phone text, whatsapp text, email text, birth_date date, cpf text, gender text, status public.patient_status NOT NULL DEFAULT 'active', treatment_goal text, observations text, emergency_contact_name text, emergency_contact_phone text, rg text, address_street text, address_number text, address_complement text, address_district text, address_city text, address_state text, address_zip text, profession text, health_plan text, documents jsonb NOT NULL DEFAULT '[]'::jsonb, created_by uuid NOT NULL, deleted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.patients TO authenticated; GRANT ALL ON public.patients TO service_role; ALTER TABLE public.patients ENABLE ROW LEVEL SECURITY; CREATE POLICY patients_ws_all ON public.patients FOR ALL TO authenticated USING (private.is_workspace_member(auth.uid(), workspace_id) OR public.is_super_admin(auth.uid())) WITH CHECK (private.is_workspace_member(auth.uid(), workspace_id) OR public.is_super_admin(auth.uid()));

CREATE TABLE public.appointments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE, patient_id uuid REFERENCES public.patients(id) ON DELETE SET NULL, professional_id uuid NOT NULL, title text NOT NULL DEFAULT 'Atendimento', type public.appointment_type NOT NULL DEFAULT 'sessao', event_date date NOT NULL, start_time time NOT NULL, end_time time NOT NULL, location text, status public.appointment_status NOT NULL DEFAULT 'scheduled', notes text, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK (end_time > start_time));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.appointments TO authenticated; GRANT SELECT ON public.appointments TO anon; GRANT ALL ON public.appointments TO service_role; ALTER TABLE public.appointments ENABLE ROW LEVEL SECURITY; CREATE POLICY appointments_ws_all ON public.appointments FOR ALL TO authenticated USING (private.is_workspace_member(auth.uid(), workspace_id) OR public.is_super_admin(auth.uid())) WITH CHECK (private.is_workspace_member(auth.uid(), workspace_id) OR public.is_super_admin(auth.uid()));

CREATE TABLE public.clinical_notes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE, patient_id uuid NOT NULL REFERENCES public.patients(id) ON DELETE CASCADE, professional_id uuid NOT NULL, title text NOT NULL, content text NOT NULL, category public.note_category NOT NULL DEFAULT 'evolucao', visibility public.note_visibility NOT NULL DEFAULT 'workspace', created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.clinical_notes TO authenticated; GRANT ALL ON public.clinical_notes TO service_role; ALTER TABLE public.clinical_notes ENABLE ROW LEVEL SECURITY; CREATE POLICY clinical_notes_ws_all ON public.clinical_notes FOR ALL TO authenticated USING (private.is_workspace_member(auth.uid(), workspace_id) OR public.is_super_admin(auth.uid())) WITH CHECK (private.is_workspace_member(auth.uid(), workspace_id) OR public.is_super_admin(auth.uid()));

CREATE TABLE public.exercises (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE, name text NOT NULL, category text, description text, instructions text, repetitions text, sets text, duration text, difficulty text, media_url text, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.exercises TO authenticated; GRANT ALL ON public.exercises TO service_role; ALTER TABLE public.exercises ENABLE ROW LEVEL SECURITY; CREATE POLICY exercises_ws_all ON public.exercises FOR ALL TO authenticated USING (private.is_workspace_member(auth.uid(), workspace_id) OR public.is_super_admin(auth.uid())) WITH CHECK (private.is_workspace_member(auth.uid(), workspace_id) OR public.is_super_admin(auth.uid()));

CREATE TABLE public.exercise_prescriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE, patient_id uuid NOT NULL REFERENCES public.patients(id) ON DELETE CASCADE, professional_id uuid NOT NULL, title text NOT NULL, description text, status text NOT NULL DEFAULT 'active', start_date date, end_date date, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.exercise_prescriptions TO authenticated; GRANT ALL ON public.exercise_prescriptions TO service_role; ALTER TABLE public.exercise_prescriptions ENABLE ROW LEVEL SECURITY; CREATE POLICY exercise_prescriptions_ws_all ON public.exercise_prescriptions FOR ALL TO authenticated USING (private.is_workspace_member(auth.uid(), workspace_id) OR public.is_super_admin(auth.uid())) WITH CHECK (private.is_workspace_member(auth.uid(), workspace_id) OR public.is_super_admin(auth.uid()));

CREATE TABLE public.exercise_prescription_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), prescription_id uuid NOT NULL REFERENCES public.exercise_prescriptions(id) ON DELETE CASCADE, exercise_id uuid REFERENCES public.exercises(id) ON DELETE SET NULL, repetitions text, sets text, duration text, notes text, order_index int NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.exercise_prescription_items TO authenticated; GRANT ALL ON public.exercise_prescription_items TO service_role; ALTER TABLE public.exercise_prescription_items ENABLE ROW LEVEL SECURITY; CREATE POLICY exercise_prescription_items_ws_all ON public.exercise_prescription_items FOR ALL TO authenticated USING (EXISTS (SELECT 1 FROM public.exercise_prescriptions p WHERE p.id = prescription_id AND (private.is_workspace_member(auth.uid(), p.workspace_id) OR public.is_super_admin(auth.uid())))) WITH CHECK (EXISTS (SELECT 1 FROM public.exercise_prescriptions p WHERE p.id = prescription_id AND (private.is_workspace_member(auth.uid(), p.workspace_id) OR public.is_super_admin(auth.uid()))));

CREATE TABLE public.charges (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE, patient_id uuid REFERENCES public.patients(id) ON DELETE SET NULL, description text NOT NULL, amount numeric(12,2) NOT NULL DEFAULT 0, due_date date NOT NULL, status public.charge_status NOT NULL DEFAULT 'pending', payment_method text, paid_at timestamptz, notes text, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.charges TO authenticated; GRANT ALL ON public.charges TO service_role; ALTER TABLE public.charges ENABLE ROW LEVEL SECURITY; CREATE POLICY charges_ws_all ON public.charges FOR ALL TO authenticated USING (private.is_workspace_member(auth.uid(), workspace_id) OR public.is_super_admin(auth.uid())) WITH CHECK (private.is_workspace_member(auth.uid(), workspace_id) OR public.is_super_admin(auth.uid()));

CREATE TABLE public.tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE, title text NOT NULL, description text, assigned_to uuid, patient_id uuid REFERENCES public.patients(id) ON DELETE SET NULL, due_date date, priority public.task_priority NOT NULL DEFAULT 'medium', status public.task_status NOT NULL DEFAULT 'pending', created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.tasks TO authenticated; GRANT ALL ON public.tasks TO service_role; ALTER TABLE public.tasks ENABLE ROW LEVEL SECURITY; CREATE POLICY tasks_ws_all ON public.tasks FOR ALL TO authenticated USING (private.is_workspace_member(auth.uid(), workspace_id) OR public.is_super_admin(auth.uid())) WITH CHECK (private.is_workspace_member(auth.uid(), workspace_id) OR public.is_super_admin(auth.uid()));

CREATE TABLE public.dictionary_terms (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid REFERENCES public.workspaces(id) ON DELETE CASCADE, term text NOT NULL, definition text NOT NULL, category text, is_global boolean NOT NULL DEFAULT false, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.dictionary_terms TO authenticated; GRANT ALL ON public.dictionary_terms TO service_role; ALTER TABLE public.dictionary_terms ENABLE ROW LEVEL SECURITY; CREATE POLICY dictionary_terms_read ON public.dictionary_terms FOR SELECT TO authenticated USING (is_global OR (workspace_id IS NOT NULL AND private.is_workspace_member(auth.uid(), workspace_id)) OR public.is_super_admin(auth.uid())); CREATE POLICY dictionary_terms_write ON public.dictionary_terms FOR ALL TO authenticated USING ((workspace_id IS NOT NULL AND private.is_workspace_member(auth.uid(), workspace_id)) OR public.is_super_admin(auth.uid())) WITH CHECK ((workspace_id IS NOT NULL AND private.is_workspace_member(auth.uid(), workspace_id)) OR public.is_super_admin(auth.uid()));

CREATE TABLE public.user_settings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE, theme public.theme_pref NOT NULL DEFAULT 'automatic', notifications_enabled boolean NOT NULL DEFAULT true, language text NOT NULL DEFAULT 'pt-BR', mode public.use_mode NOT NULL DEFAULT 'professional', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id, workspace_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.user_settings TO authenticated; GRANT ALL ON public.user_settings TO service_role; ALTER TABLE public.user_settings ENABLE ROW LEVEL SECURITY; CREATE POLICY user_settings_self_all ON public.user_settings FOR ALL TO authenticated USING (user_id = auth.uid() OR public.is_super_admin(auth.uid())) WITH CHECK (user_id = auth.uid() OR public.is_super_admin(auth.uid()));

CREATE TABLE public.subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE, plan public.plan_kind NOT NULL DEFAULT 'free', status text NOT NULL DEFAULT 'trial', started_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz, provider text, provider_subscription_id text, monthly_price numeric(10,2) DEFAULT 0, due_day int DEFAULT 10, current_period_start date, current_period_end date, next_due_date date, payment_method text, auto_block_after_days int DEFAULT 7, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.subscriptions TO authenticated; GRANT ALL ON public.subscriptions TO service_role; ALTER TABLE public.subscriptions ENABLE ROW LEVEL SECURITY; CREATE POLICY subscriptions_ws_all ON public.subscriptions FOR ALL TO authenticated USING (private.is_workspace_member(auth.uid(), workspace_id) OR public.is_super_admin(auth.uid())) WITH CHECK (private.is_workspace_member(auth.uid(), workspace_id) OR public.is_super_admin(auth.uid()));

CREATE TABLE public.notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE, user_id uuid NOT NULL, title text NOT NULL, message text NOT NULL, type text NOT NULL DEFAULT 'system', read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.notifications TO authenticated; GRANT ALL ON public.notifications TO service_role; ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY; CREATE POLICY notifications_self_all ON public.notifications FOR ALL TO authenticated USING (user_id = auth.uid() OR public.is_super_admin(auth.uid())) WITH CHECK (user_id = auth.uid() OR public.is_super_admin(auth.uid()));

CREATE TABLE public.audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid REFERENCES public.workspaces(id) ON DELETE CASCADE, user_id uuid, action text NOT NULL, entity_type text NOT NULL, entity_id uuid, old_data jsonb, new_data jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.audit_logs TO authenticated; GRANT ALL ON public.audit_logs TO service_role; ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY; CREATE POLICY audit_logs_read ON public.audit_logs FOR SELECT TO authenticated USING (public.is_super_admin(auth.uid()) OR (workspace_id IS NOT NULL AND private.is_workspace_member(auth.uid(), workspace_id))); CREATE POLICY audit_logs_insert ON public.audit_logs FOR INSERT TO authenticated WITH CHECK (public.is_super_admin(auth.uid()) OR (workspace_id IS NOT NULL AND private.is_workspace_member(auth.uid(), workspace_id)));

CREATE TABLE public.tool_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE, patient_id uuid REFERENCES public.patients(id) ON DELETE SET NULL, tool_type text NOT NULL, input_data jsonb NOT NULL DEFAULT '{}'::jsonb, result_data jsonb NOT NULL DEFAULT '{}'::jsonb, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.tool_records TO authenticated; GRANT ALL ON public.tool_records TO service_role; ALTER TABLE public.tool_records ENABLE ROW LEVEL SECURITY; CREATE POLICY tool_records_ws_all ON public.tool_records FOR ALL TO authenticated USING (private.is_workspace_member(auth.uid(), workspace_id) OR public.is_super_admin(auth.uid())) WITH CHECK (private.is_workspace_member(auth.uid(), workspace_id) OR public.is_super_admin(auth.uid()));

CREATE TABLE public.daily_quotes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), text text NOT NULL, author text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.daily_quotes TO anon; GRANT SELECT, INSERT, UPDATE, DELETE ON public.daily_quotes TO authenticated; GRANT ALL ON public.daily_quotes TO service_role; ALTER TABLE public.daily_quotes ENABLE ROW LEVEL SECURITY; CREATE POLICY daily_quotes_public_read ON public.daily_quotes FOR SELECT USING (active = true OR public.is_super_admin(auth.uid())); CREATE POLICY daily_quotes_admin_all ON public.daily_quotes FOR ALL TO authenticated USING (public.is_super_admin(auth.uid())) WITH CHECK (public.is_super_admin(auth.uid()));

CREATE TABLE public.crm_leads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE, owner_user_id uuid, name text NOT NULL, email text, phone text, source text, stage text NOT NULL DEFAULT 'novo', tags text[] NOT NULL DEFAULT '{}', value_cents int NOT NULL DEFAULT 0, notes text, next_action_at timestamptz, last_contact_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.crm_leads TO authenticated; GRANT ALL ON public.crm_leads TO service_role; ALTER TABLE public.crm_leads ENABLE ROW LEVEL SECURITY; CREATE POLICY crm_leads_ws_all ON public.crm_leads FOR ALL TO authenticated USING (private.is_workspace_member(auth.uid(), workspace_id) OR public.is_super_admin(auth.uid())) WITH CHECK (private.is_workspace_member(auth.uid(), workspace_id) OR public.is_super_admin(auth.uid()));

CREATE TABLE public.crm_activities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid NOT NULL REFERENCES public.crm_leads(id) ON DELETE CASCADE, workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE, type text NOT NULL, content text NOT NULL, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.crm_activities TO authenticated; GRANT ALL ON public.crm_activities TO service_role; ALTER TABLE public.crm_activities ENABLE ROW LEVEL SECURITY; CREATE POLICY crm_activities_ws_all ON public.crm_activities FOR ALL TO authenticated USING (private.is_workspace_member(auth.uid(), workspace_id) OR public.is_super_admin(auth.uid())) WITH CHECK (private.is_workspace_member(auth.uid(), workspace_id) OR public.is_super_admin(auth.uid()));

CREATE TABLE public.booking_links (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE, owner_user_id uuid NOT NULL, slug text NOT NULL UNIQUE, title text NOT NULL, description text, duration_min int NOT NULL DEFAULT 50, buffer_min int NOT NULL DEFAULT 10, timezone text NOT NULL DEFAULT 'America/Sao_Paulo', working_days int[] NOT NULL DEFAULT '{1,2,3,4,5}', start_time time NOT NULL DEFAULT '08:00', end_time time NOT NULL DEFAULT '18:00', advance_days int NOT NULL DEFAULT 30, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.booking_links TO anon; GRANT SELECT, INSERT, UPDATE, DELETE ON public.booking_links TO authenticated; GRANT ALL ON public.booking_links TO service_role; ALTER TABLE public.booking_links ENABLE ROW LEVEL SECURITY; CREATE POLICY booking_links_public_read ON public.booking_links FOR SELECT TO anon USING (active = true); CREATE POLICY booking_links_ws_all ON public.booking_links FOR ALL TO authenticated USING (private.is_workspace_member(auth.uid(), workspace_id) OR owner_user_id = auth.uid() OR public.is_super_admin(auth.uid())) WITH CHECK (private.is_workspace_member(auth.uid(), workspace_id) OR owner_user_id = auth.uid() OR public.is_super_admin(auth.uid()));
CREATE POLICY appointments_public_booking_slots ON public.appointments FOR SELECT TO anon USING (EXISTS (SELECT 1 FROM public.booking_links bl WHERE bl.workspace_id = appointments.workspace_id AND bl.owner_user_id = appointments.professional_id AND bl.active));

CREATE TABLE public.booking_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_link_id uuid NOT NULL REFERENCES public.booking_links(id) ON DELETE CASCADE, workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE, owner_user_id uuid NOT NULL, lead_name text NOT NULL, lead_email text, lead_phone text, notes text, scheduled_at timestamptz NOT NULL, duration_min int NOT NULL DEFAULT 50, status text NOT NULL DEFAULT 'confirmed', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.booking_requests TO authenticated; GRANT ALL ON public.booking_requests TO service_role; ALTER TABLE public.booking_requests ENABLE ROW LEVEL SECURITY; CREATE POLICY booking_requests_ws_all ON public.booking_requests FOR ALL TO authenticated USING (private.is_workspace_member(auth.uid(), workspace_id) OR owner_user_id = auth.uid() OR public.is_super_admin(auth.uid())) WITH CHECK (private.is_workspace_member(auth.uid(), workspace_id) OR owner_user_id = auth.uid() OR public.is_super_admin(auth.uid()));

CREATE TABLE public.invoices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE, amount numeric(12,2) NOT NULL DEFAULT 0, due_date date NOT NULL DEFAULT CURRENT_DATE, status text NOT NULL DEFAULT 'open', description text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
