CREATE OR REPLACE FUNCTION public.record_event(_event_type text, _workspace_id uuid DEFAULT NULL, _metadata jsonb DEFAULT '{}'::jsonb, _source text DEFAULT 'app') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_id uuid; BEGIN INSERT INTO public.events(event_type, workspace_id, user_id, source, metadata) VALUES (_event_type, _workspace_id, auth.uid(), _source, _metadata) RETURNING id INTO v_id; RETURN v_id; END; $$;
GRANT EXECUTE ON FUNCTION public.record_event(text, uuid, jsonb, text) TO authenticated;

