GRANT SELECT, INSERT, UPDATE, DELETE ON public.blocked_identifiers TO authenticated; GRANT ALL ON public.blocked_identifiers TO service_role; ALTER TABLE public.blocked_identifiers ENABLE ROW LEVEL SECURITY; CREATE POLICY blocked_identifiers_super_all ON public.blocked_identifiers FOR ALL TO authenticated USING (public.is_super_admin(auth.uid())) WITH CHECK (public.is_super_admin(auth.uid()));
CREATE TABLE public.rate_limit_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), key text NOT NULL UNIQUE, limit_count int NOT NULL DEFAULT 60, window_seconds int NOT NULL DEFAULT 60, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.rate_limit_rules TO authenticated; GRANT ALL ON public.rate_limit_rules TO service_role; ALTER TABLE public.rate_limit_rules ENABLE ROW LEVEL SECURITY; CREATE POLICY rate_limit_rules_super_all ON public.rate_limit_rules FOR ALL TO authenticated USING (public.is_super_admin(auth.uid())) WITH CHECK (public.is_super_admin(auth.uid()));
CREATE TABLE public.prompt_injection_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), pattern text NOT NULL, severity text NOT NULL DEFAULT 'medium', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.prompt_injection_rules TO authenticated; GRANT ALL ON public.prompt_injection_rules TO service_role; ALTER TABLE public.prompt_injection_rules ENABLE ROW LEVEL SECURITY; CREATE POLICY prompt_injection_rules_super_all ON public.prompt_injection_rules FOR ALL TO authenticated USING (public.is_super_admin(auth.uid())) WITH CHECK (public.is_super_admin(auth.uid()));

CREATE INDEX workspaces_owner_idx ON public.workspaces(owner_id); CREATE INDEX profiles_auth_user_idx ON public.profiles(auth_user_id); CREATE INDEX workspace_members_user_idx ON public.workspace_members(user_id); CREATE INDEX patients_ws_idx ON public.patients(workspace_id); CREATE INDEX appointments_ws_date_idx ON public.appointments(workspace_id, event_date); CREATE INDEX booking_links_slug_idx ON public.booking_links(slug); CREATE INDEX crm_leads_ws_idx ON public.crm_leads(workspace_id); CREATE INDEX sticky_notes_user_idx ON public.sticky_notes(user_id);
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['workspaces','profiles','workspace_members','patients','appointments','clinical_notes','exercises','exercise_prescriptions','charges','tasks','dictionary_terms','user_settings','subscriptions','crm_leads','booking_links','affiliates','affiliate_commission_rules','security_incidents','legal_documents','sticky_notes'] LOOP EXECUTE format('CREATE TRIGGER set_%s_updated BEFORE UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.set_updated_at()', t, t); END LOOP; END $$;
